  ('c65ead08-a6b2-53ce-b83b-ee2e7206aaad', '81c9d092-50b4-51ca-8646-94251d686060', 'A', 'Hormone therapy for all', false, 0),
  ('22671e1b-4d80-5a15-b9f5-711de207661b', '81c9d092-50b4-51ca-8646-94251d686060', 'B', 'No preventive measures', false, 1),
  ('38eda905-27f6-576b-9783-bcc2d415c77a', '81c9d092-50b4-51ca-8646-94251d686060', 'C', 'Iron supplements', false, 2),
  ('cfe7fac7-bf86-5cb5-8087-9f6a95fbdbd7', '81c9d092-50b4-51ca-8646-94251d686060', 'D', 'Bone protection with a bisphosphonate plus calcium and vitamin D', true, 3),
  ('762a1be5-9e80-5c4a-9b9e-341041ceca07', '81c9d092-50b4-51ca-8646-94251d686060', 'E', 'Vitamin C', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 45 year old woman with chronic back pain is taking 30 mg of oral morphine twice daily. She has severe constipation. Which laxative combination is MOST appropriate?', 'Opioid-induced constipation should be prevented by co-prescribing laxatives. A stimulant (senna or bisacodyl) plus a softener or osmotic laxative (docusate, macrogol) is used. Bulk-forming laxatives should be avoided. If this fails, a peripherally acting mu-opioid receptor antagonist (methylnaltrexone or naloxegol) can be considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('292a1578-7338-5fd0-8ae9-3b454934b8b0', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'A', 'Rectal enemas daily', false, 0),
  ('365fe4c1-3ae6-52e3-ba2c-16f7f5322425', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'B', 'Stop all opioids immediately', false, 1),
  ('4041f883-5fab-59a0-8f18-2169da519795', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'C', 'Stimulant laxative (senna) plus a softener or osmotic laxative', true, 2),
  ('fa6afcfe-09fd-5923-948c-fc7cc9d1830b', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'D', 'Bulk-forming laxative only', false, 3),
  ('01ed7706-984a-5c65-a084-c4110c2699ba', '5e6c7e4b-9300-5ad7-9e7b-117bdbf76b98', 'E', 'Loperamide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('57cff6df-8958-5196-ad14-4b5693d49b4c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 32 year old woman takes the combined oral contraceptive pill. She is starting rifampicin for latent TB. What is the SINGLE most appropriate contraceptive advice?', 'Rifampicin is a potent enzyme inducer that makes most hormonal contraceptives ineffective (COCP, POP, implant, patch, ring). Reliable options are the copper IUD, LNG-IUS or DMPA injection. Contraceptive precautions continue for 28 days after stopping the enzyme inducer. Rifampicin also lowers levels of warfarin and many other drugs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a68747a4-0bf5-550e-8866-845a088de955', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'A', 'Continue the COCP as normal', false, 0),
  ('a5916d48-d310-5d70-bdd7-c7def2d81e01', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'B', 'Use the implant', false, 1),
  ('932b22f7-ec90-5bac-acb4-fc3da22c1f39', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'C', 'Use a non-hormonal method (copper IUD) or a method unaffected by enzyme inducers, during treatment and for 28 days after', true, 2),
  ('30349c3e-3981-52d2-9bd9-d9a1bea57790', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'D', 'Switch to the progestogen-only pill', false, 3),
  ('1b876851-3d9b-5556-ab01-e192f8e4dbcb', '57cff6df-8958-5196-ad14-4b5693d49b4c', 'E', 'Double the COCP dose for 3 days', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 72 year old man takes digoxin and has developed nausea and visual disturbance. His eGFR has fallen recently. Which electrolyte disturbance would MOST increase his risk of digoxin toxicity?', 'Digoxin competes with potassium at the Na+/K+-ATPase, so hypokalaemia increases toxicity. Hypomagnesaemia and hypercalcaemia also increase toxicity. Reduced renal function causes accumulation because digoxin is cleared by the kidneys. Drugs that increase digoxin levels include amiodarone, verapamil and macrolides. Severe toxicity is treated with DigiFab.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7a841cb9-d065-5994-ac59-17b88a554dda', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'A', 'Hyperkalaemia', false, 0),
  ('934be068-3b61-57ae-a2e2-9ea3426047d2', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'B', 'Hypercalcaemia only', false, 1),
  ('4b98b056-4bca-567c-b9b2-c55d0f4e642d', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'C', 'Hypokalaemia', true, 2),
  ('284f1757-4080-5d1f-8f07-02d9b9edea61', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'D', 'Hypermagnesaemia', false, 3),
  ('a6ca31f0-46f3-564d-9359-58046d8a8675', '17f4c6cb-4c79-5357-a4cc-feb22391bb4f', 'E', 'Hyponatraemia', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2c462591-7190-5c60-b0b8-cce196c753a9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 70 year old man with Parkinson''s disease is admitted with confusion and is nil by mouth. His usual medication is co-careldopa. What is the SINGLE most appropriate action?', 'Omitting or delaying Parkinson''s medication can cause severe rigidity, inability to swallow, aspiration and neuroleptic malignant-like syndrome. Doses must be given on time. If the patient cannot swallow, options include NG administration or a transdermal rotigotine patch. Dopamine antagonists (haloperidol, metoclopramide, prochlorperazine) must be avoided. Domperidone is a safer antiemetic.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('933526fb-313b-57ca-9763-37a61b99265d', '2c462591-7190-5c60-b0b8-cce196c753a9', 'A', 'Give metoclopramide for nausea', false, 0),
  ('afe0698b-85ba-5af5-af76-1d38f8adacc4', '2c462591-7190-5c60-b0b8-cce196c753a9', 'B', 'Withhold all Parkinson''s medication until he can swallow', false, 1),
  ('e57e6c33-88d7-524a-8bbb-0cdae10a6156', '2c462591-7190-5c60-b0b8-cce196c753a9', 'C', 'Give haloperidol for confusion', false, 2),
  ('a75b9523-f662-5c29-809d-eeab7edda993', '2c462591-7190-5c60-b0b8-cce196c753a9', 'D', 'Stop co-careldopa permanently', false, 3),
  ('ffa93a98-7d8b-5197-9ec4-98c27534bc30', '2c462591-7190-5c60-b0b8-cce196c753a9', 'E', 'Ensure Parkinson''s medication is given on time (e.g. via nasogastric tube or a rotigotine patch if unable to swallow)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 26 year old man with depression has taken a large overdose of citalopram. His ECG shows a QTc of 560 ms. What is the SINGLE most important concern?', 'Citalopram and escitalopram cause dose-dependent QT prolongation, and overdose can lead to torsades de pointes. Other QT-prolonging drugs include antipsychotics, macrolides, quinolones, ondansetron, methadone and class III antiarrhythmics. Torsades is treated with IV magnesium sulfate. Electrolytes (K, Mg, Ca) should be corrected.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('65d0cbb9-c55c-5a0d-9e3c-6ec6402b9ef4', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'A', 'Renal failure', false, 0),
  ('9b89f3bd-e081-5240-bd4e-3ce96488f079', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'B', 'Hepatotoxicity', false, 1),
  ('84a6d2a0-e8de-5a91-8738-e4069fd48c58', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'C', 'Hypoglycaemia', false, 2),
  ('8b8dc26b-8106-5114-855f-40b93b594da1', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'D', 'Torsades de pointes (polymorphic VT) and sudden cardiac death', true, 3),
  ('314fe595-5d55-5065-8887-b30841d663eb', 'feee521f-6e4f-538e-9c8f-53aca4a1b5e4', 'E', 'Bone marrow suppression', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('07a8a90e-6376-54cf-be5e-0efb0706df74', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 72 year old woman taking methotrexate weekly for rheumatoid arthritis attends for routine monitoring. Which set of blood tests is MOST important?', 'Methotrexate monitoring (FBC, U&E, LFT) is done every 2 weeks initially, then every 3 months once stable. Side effects include myelosuppression, hepatotoxicity, pneumonitis, mucositis and teratogenicity. It is taken once weekly with folic acid on a different day. Trimethoprim and NSAIDs increase toxicity. Prescribing errors (daily instead of weekly) have caused deaths.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5b9a5d5d-8ed0-5175-9c54-de5eee39aa23', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'A', 'Vitamin D only', false, 0),
  ('625001a6-26a6-5cd1-bbc8-49e5a7780090', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'B', 'Thyroid function and HbA1c', false, 1),
  ('b566a121-1cef-567f-9150-f4dafdd9b89c', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'C', 'Lipids only', false, 2),
  ('a2f08d62-214b-5345-988d-479bf18a0b82', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'D', 'Amylase and lipase', false, 3),
  ('68bfd2fa-c011-5969-9d99-0598db25c53c', '07a8a90e-6376-54cf-be5e-0efb0706df74', 'E', 'Full blood count, renal function and liver function tests', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dbf935ac-8bc9-58f5-94f0-548790e7c983', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 30 year old woman with known G6PD deficiency has a UTI. Which antibiotic should be AVOIDED?', 'In G6PD deficiency, drugs that cause oxidative stress can trigger haemolysis: nitrofurantoin, quinolones (ciprofloxacin), sulfonamides (co-trimoxazole), dapsone, primaquine and high-dose aspirin. Cephalosporins, penicillins and fosfomycin are generally safe. Patients should know which drugs to avoid.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('dc61b705-60f9-50c1-8448-38e39c04b30e', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'A', 'Cefalexin', false, 0),
  ('7fd2b78c-b8cb-5f52-b457-aca1f76cfd0d', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'B', 'Pivmecillinam', false, 1),
  ('967ac291-87c7-5a74-be0d-700f10d9c39e', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'C', 'Amoxicillin (if sensitive)', false, 2),
  ('6dc89973-0b44-5b93-83f3-4017fc21225d', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'D', 'Nitrofurantoin', true, 3),
  ('0c7e010f-2e8e-5c41-9c17-d25d5417c237', 'dbf935ac-8bc9-58f5-94f0-548790e7c983', 'E', 'Fosfomycin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 64 year old man with CKD (eGFR 22 mL/min/1.73m2) and type 2 diabetes is taking metformin 1 g twice daily. What is the SINGLE most appropriate action?', 'Metformin is contraindicated with an eGFR under 30 because of the risk of lactic acidosis, and the dose should be reviewed (usually halved) at an eGFR under 45. It should be paused during acute illness with dehydration or AKI (sick day rules) and around iodinated contrast in at-risk patients. Many diabetes drugs need dose adjustment in CKD.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c4221ca2-f621-5827-bf29-8b3a967e1483', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'A', 'Stop metformin because eGFR is below 30', true, 0),
  ('8eb799b8-ae73-591a-a2c8-6773cec02f08', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'B', 'Continue at the same dose', false, 1),
  ('eb33c6d9-052e-5f4e-84e7-74a4b5aaf7df', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'C', 'Increase metformin', false, 2),
  ('f8f60f83-1271-5ff3-9227-8a1222ea47b5', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'D', 'Switch to IV insulin', false, 3),
  ('245c3016-d943-5824-a72d-c9fc19acc43a', '4ec350b0-7ea1-562f-a988-7857ea91f4d7', 'E', 'Add gliclazide and continue metformin unchanged', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8722c344-58c6-509f-af1d-f5f53688437c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 22 year old man with acne is prescribed doxycycline. Which advice is MOST important?', 'Tetracyclines can cause oesophageal ulceration, so they are taken upright with water. They cause photosensitivity. Absorption is reduced by milk, antacids, iron, calcium and zinc. Tetracyclines are contraindicated in pregnancy, breastfeeding and children under 12, because they stain teeth and affect bone growth.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('19c7a003-8d46-5822-b7d2-9708203038e6', '8722c344-58c6-509f-af1d-f5f53688437c', 'A', 'Doxycycline is safe in pregnancy', false, 0),
  ('efcdac11-f535-5f4b-96ac-d2fca970d924', '8722c344-58c6-509f-af1d-f5f53688437c', 'B', 'Take at bedtime lying down', false, 1),
  ('6d8fdc6f-40ea-535d-ba17-59f6f21f67b0', '8722c344-58c6-509f-af1d-f5f53688437c', 'C', 'Take with a full glass of water while sitting or standing, avoid lying down for 30 minutes, and avoid strong sunlight', true, 2),
  ('225d7e0a-36b3-5f18-a9d2-f84bbcf4276a', '8722c344-58c6-509f-af1d-f5f53688437c', 'D', 'Take with milk', false, 3),
  ('327dae7c-a012-520a-bfbf-1114d41491f0', '8722c344-58c6-509f-af1d-f5f53688437c', 'E', 'Take with antacids', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c1122ecd-b505-5602-b383-1e753169570d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 45 year old woman with hypertension takes lisinopril. She attends with a dry cough. What is the SINGLE most appropriate alternative antihypertensive?', 'Dry cough is a class effect of ACE inhibitors (bradykinin accumulation), so switching to another ACE inhibitor will not help. An ARB such as losartan or candesartan blocks the angiotensin II receptor without affecting bradykinin, and is the appropriate switch. Renal function and potassium should be checked after starting.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('40eaedf4-ca04-5bbb-9c4c-a40dadc3a2d9', 'c1122ecd-b505-5602-b383-1e753169570d', 'A', 'Losartan', true, 0),
  ('9b57b99e-fa41-5081-8b89-32c355493ef6', 'c1122ecd-b505-5602-b383-1e753169570d', 'B', 'Perindopril', false, 1),
  ('cfe84567-a8bc-5d92-8ae5-f1ab56602705', 'c1122ecd-b505-5602-b383-1e753169570d', 'C', 'Ramipril', false, 2),
  ('61073181-f3b7-5879-b0f4-cea39b573f85', 'c1122ecd-b505-5602-b383-1e753169570d', 'D', 'Enalapril', false, 3),
  ('99921072-50de-56a3-847a-bd9358494456', 'c1122ecd-b505-5602-b383-1e753169570d', 'E', 'Captopril', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0c9d9eb5-0349-5600-8d80-df80076026ac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 40 year old woman is found at home in a drowsy state and taken to the Emergency Department. She has had multiple Emergency Department admissions for severe and recurrent depression. Her pulse rate is 108 bpm. She is confused with dilated pupils, dry mucous membranes and a palpable bladder to the umbilicus. Which medication is most likely responsible for her clinical findings?', 'Anticholinergic features (tachycardia, confusion, dilated pupils, dry mucous membranes, urinary retention) after an overdose in a person with depression point to a tricyclic antidepressant such as amitriptyline. TCA overdose can cause seizures and a broad QRS with arrhythmias, which are treated with IV sodium bicarbonate. SSRIs are much safer in overdose.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1d6b1d1c-4bf4-5e3e-8747-c423100ec15c', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'A', 'Amitriptyline', true, 0),
  ('a3efb353-7616-5520-8fef-3ab1d6856fe9', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'B', 'Fluoxetine', false, 1),
  ('261ddc2d-403a-5427-986d-bef20c4b4eb1', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'C', 'Lithium', false, 2),
  ('b6c22a08-0356-5e87-8629-20baa2629d4c', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'D', 'Phenelzine', false, 3),
  ('bfec6f71-fc56-5bea-8ca6-677c9c187f04', '0c9d9eb5-0349-5600-8d80-df80076026ac', 'E', 'Venlafaxine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 54 year old man has swelling of both ankles and is seen in the GP surgery. He has hypertension and takes amlodipine. His pulse rate is 92 bpm and BP 162/90 mmHg. His BMI is 41kg/m². His jugular venous pressure is not raised. Urinalysis shows no abnormality. He has pitting oedema of both ankles. Which is the most likely cause of his ankle swelling?', 'Calcium channel blockers such as amlodipine commonly cause dose-related ankle oedema by dilating precapillary arterioles. A normal JVP and normal urinalysis make heart failure and nephrotic syndrome less likely. Options include reducing the dose, switching drug class, or adding an ACE inhibitor or ARB, which reduces CCB oedema.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('023f85b5-89f5-5a72-b3f9-f45c1a0e613e', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'A', 'Drug side effect', true, 0),
  ('813bf359-cce6-5f72-aece-f959f3a54855', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'B', 'Heart failure', false, 1),
  ('be8b843d-17e6-5062-aa8a-11c10c2a9603', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'C', 'Lymphoedema', false, 2),
  ('4b54a402-003e-5891-9c6d-0b0ebd4f7e96', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'D', 'Nephrotic syndrome', false, 3),
  ('5e7164e3-9ca6-57cc-a94e-0110881d1a75', '77e6b68f-7f8a-5fbc-a59b-63a440083f59', 'E', 'Obesity', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 73 year old woman has blood taken for her international normalised ratio (INR) and is seen in the GP Surgery. She is taking clarithromycin for a chest infection. She has hypertension, osteoporosis, trigeminal neuralgia and a metallic mitral valve replacement 20 years ago. She takes warfarin, amlodipine, atorvastatin, carbamazepine and sodium risedronate. Investigations: INR 1.3 (2.5) Which medication is most likely to have interacted with warfarin to cause this INR?', 'Carbamazepine is a potent enzyme inducer (CYP450) that increases warfarin metabolism and lowers the INR. Clarithromycin is an enzyme inhibitor that raises the INR. For an INR that has fallen and is harder to control, carbamazepine is the likely culprit. INR should be monitored closely when interacting drugs are started or stopped.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c3b3593e-c87e-58f1-b577-944e8bfc81eb', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'A', 'Amlodipine', false, 0),
  ('829c3d1c-3330-5c65-b8dc-a75c77f89773', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'B', 'Atorvastatin', false, 1),
  ('e2cc597b-ee20-5b0f-a948-d026c3a648eb', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'C', 'Carbamazepine', true, 2),
  ('ccfeefe6-7e69-5837-b884-de7a575d39e7', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'D', 'Clarithromycin', false, 3),
  ('a8c719b2-660e-5664-abb7-6b54bf9f5288', 'ad7029d8-890f-5b0c-b924-2f6f2dac52eb', 'E', 'Risedronate sodium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000034', 'sba', 'A 72 year old man has worsening breathlessness and ankle swelling for 2 months and is seen by his GP. He is diagnosed with heart failure and prescribed ramipril. He is asked to attend for a ‘monitoring blood test’ in 2 weeks. Which is the most appropriate monitoring test to carry out?', 'After starting an ACE inhibitor, renal function and electrolytes (creatinine and potassium) should be checked within 1-2 weeks and after each dose increase, because of the risk of hyperkalaemia and kidney impairment. A rise in creatinine of up to 30% or potassium up to 6.0 mmol/L may be acceptable.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('46705aef-88d7-51f9-be81-e1ae28efbb5a', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'A', 'Brain natriuretic peptide', false, 0),
  ('6627bdb5-c361-51cb-8fd4-5b3e52e2c3b3', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'B', 'Creatine kinase', false, 1),
  ('84ea0c0c-1224-5bbe-a1b6-ffa2352554c1', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'C', 'Full blood count', false, 2),
  ('c8935e21-82d7-532d-88c8-6581b4b3252a', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'D', 'Liver function tests', false, 3),
  ('300c6e22-dcf2-5884-910d-a2ba3c9d656b', '9ba82409-881b-5fb9-b715-bcab4e22cf5f', 'E', 'Renal function', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 70 year old man with COPD is given high-flow oxygen through a non-rebreather mask by paramedics and becomes increasingly drowsy. An arterial blood gas on 15 L/min oxygen shows pH 7.21, PaCO2 9.4 kPa, PaO2 24 kPa and bicarbonate 27 mmol/L. Which of the following BEST describes this blood gas?', 'The pH is low (acidaemia) and PaCO2 is high, so the acidosis is respiratory. Bicarbonate is only at the upper limit of normal and has not risen enough to offset the CO2, so this is acute and uncompensated, likely from uncontrolled oxygen in a CO2-retainer. Target saturations of 88-92% with controlled oxygen through a Venturi mask. If acidosis persists despite optimal medical treatment, NIV is indicated (pH below 7.35 and PaCO2 above 6.5 kPa).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d708cb0f-eb2b-5b9b-965a-0813554c3936', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'A', 'Acute respiratory acidosis', true, 0),
  ('8395ace6-1c64-5395-a122-dee4c661e2a3', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'B', 'Mixed respiratory and metabolic acidosis', false, 1),
  ('7bf9348d-c50f-54f1-8077-fface3a45843', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'C', 'Metabolic alkalosis', false, 2),
  ('8f3dc252-72c1-5302-a2a0-15e13348b679', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'D', 'Metabolic acidosis with respiratory compensation', false, 3),
  ('e1c6c9f6-3bc9-5a48-8f8d-baae21a4190b', 'e4d1d749-c75b-5999-aa7a-2354d8e9d2c0', 'E', 'Compensated respiratory acidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 25 year old man with type 1 diabetes has an arterial blood gas showing pH 7.18, PaCO2 2.9 kPa, bicarbonate 8 mmol/L, sodium 138 mmol/L and chloride 100 mmol/L. What is the anion gap and the BEST description of this acid-base disturbance?', 'Anion gap = Na - (Cl + HCO3) = 138 - (100 + 8) = 30 mmol/L (normal is about 8-14 without potassium). Low pH and low bicarbonate show a metabolic acidosis, and the low PaCO2 is respiratory compensation (Kussmaul breathing). Causes of a high anion gap acidosis include ketoacidosis (here likely DKA), lactic acidosis, renal failure and toxins (methanol, ethylene glycol, salicylates). Normal anion gap acidosis is seen with diarrhoea or renal tubular acidosis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bb1fe868-0d58-5e5d-8cdf-021d067c49cf', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'A', 'Anion gap 8 mmol/L; mixed respiratory and metabolic alkalosis', false, 0),
  ('f24a8f16-92ab-5263-b26d-6a600a0372cc', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'B', 'Anion gap 12 mmol/L; normal anion gap metabolic acidosis', false, 1),
  ('789e9540-ea9c-5d8a-bd5c-4b597ad54bed', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'C', 'Anion gap 38 mmol/L; metabolic alkalosis', false, 2),
  ('c5ed9926-6d79-5c7b-96f5-b460cdf28aa9', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'D', 'Anion gap 30 mmol/L; high anion gap metabolic acidosis with respiratory compensation', true, 3),
  ('b56e1180-da2b-590a-9aa0-94f1f579a14e', 'c8158c84-17c9-5e45-ae7a-2b93dacbfbfa', 'E', 'Anion gap 30 mmol/L; respiratory acidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b02c4f7f-e009-50b9-91d4-06bc608000ae', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 62 year old woman in the Emergency Department with sepsis from a urinary source has received 30 mL/kg of IV crystalloid. Her mean arterial pressure remains 55 mmHg and lactate is 5.1 mmol/L. She has had IV antibiotics. What is the SINGLE most appropriate next step?', 'Persistent hypotension (MAP below 65 mmHg) and a raised lactate despite adequate fluid resuscitation means septic shock. She needs critical care referral for vasopressors (noradrenaline first-line), targeting a MAP of 65 mmHg or above, with arterial line monitoring. Too much fluid causes oedema and harm. IV hydrocortisone is considered if vasopressor needs keep rising.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cdb6ea9d-a4aa-5b84-ac52-a9903e998f74', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'A', 'Continue fluids indefinitely until BP normalises', false, 0),
  ('3c040307-5de4-55fa-8d89-54530479f5ab', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'B', 'IV hydrocortisone as first-line', false, 1),
  ('1bdf8d91-9d42-50c2-a34b-9bbd579cee28', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'C', 'Stop antibiotics and wait for cultures', false, 2),
  ('2e72cfcc-3695-5edc-ba99-7a47b0ba0f3a', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'D', 'Refer to critical care for vasopressor support (noradrenaline)', true, 3),
  ('c53f63e9-0bfa-5758-bfcb-d52314d9a534', 'b02c4f7f-e009-50b9-91d4-06bc608000ae', 'E', 'Oral fluids and ward observation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 68 year old man is in ICU on a ventilator for pneumonia. His PaO2/FiO2 ratio is 12 kPa (90 mmHg), with bilateral infiltrates on chest X-ray not explained by heart failure. What is the SINGLE most appropriate ventilation strategy?', 'Acute respiratory distress syndrome (Berlin definition) is acute onset, bilateral opacities and PaO2/FiO2 300 mmHg or below with PEEP of 5 or more, not fully explained by heart failure. A ratio under 100 is severe. Management is lung-protective ventilation (low tidal volumes, plateau pressure under 30 cmH2O), appropriate PEEP, prone positioning for severe ARDS, conservative fluids and treating the cause.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2ca17ba9-5fde-563d-8af3-e351ab82cb3e', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'A', 'Bronchoscopy for all', false, 0),
  ('d0b0e7ea-0f4b-576e-bc63-da2c655b9dea', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'B', 'Diuretics only', false, 1),
  ('186802a5-2dec-5971-82f7-b1c30f700136', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'C', 'High tidal volume ventilation (12 mL/kg)', false, 2),
  ('c5df7e54-1d19-565e-a239-e5d8bfb0fc98', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'D', 'Zero PEEP', false, 3),
  ('c1899603-6a50-5870-8f9e-8f96593acd99', '7c3e5e7d-c199-5fdc-ba8c-913eb1896b4b', 'E', 'Lung-protective ventilation (low tidal volume 6 mL/kg ideal body weight) with prone positioning', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 55 year old woman is admitted to ICU with septic shock. After 30 mL/kg fluid, her MAP is 58 mmHg despite noradrenaline. What is the MAP target for vasopressor therapy?', 'The Surviving Sepsis Campaign recommends an initial MAP target of 65 mmHg with noradrenaline as the first-line vasopressor. Vasopressin is added if MAP stays inadequate, and adrenaline can also be considered. IV hydrocortisone is considered for ongoing vasopressor requirement. Lactate is repeated to guide resuscitation.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('220ae973-fc2b-5484-8742-5bbedaff2531', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'A', 'No target', false, 0),
  ('d7698df6-aedb-5423-8ba1-4b0fb520609c', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'B', '50 mmHg', false, 1),
  ('563ae475-5b93-5053-8310-e98fd18185b8', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'C', '80 mmHg', false, 2),
  ('234f97a0-7f25-557d-b2bc-dece871476c9', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'D', '100 mmHg', false, 3),
  ('96e72c50-0def-5223-8b1f-1ce721ecea81', '1f0e7f65-4b33-5896-900b-1beed3e93f1c', 'E', '65 mmHg', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6f02ffec-70ff-5e7f-995a-500699780d27', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 75 year old man with an acute kidney injury and sepsis has had his NEWS2 score increase from 3 to 7 over 4 hours. According to NEWS2 guidance, what is the SINGLE most appropriate response?', 'NEWS2: a score of 0-4 needs routine or ward-based response, 5-6 (or 3 in one parameter) an urgent response (ward clinician within 1 hour), and 7 or more an emergency response with a critical care outreach team and continuous monitoring. NEWS2 aggregates respiratory rate, saturations, oxygen use, temperature, systolic BP, heart rate and consciousness (including new confusion).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7332a81f-1a69-528e-bb79-02755b9b831a', '6f02ffec-70ff-5e7f-995a-500699780d27', 'A', 'Routine ward review tomorrow', false, 0),
  ('85503187-3ac2-5b58-89cd-981bd21d8d3a', '6f02ffec-70ff-5e7f-995a-500699780d27', 'B', 'Urgent (emergency) response with a clinical team competent in critical care, with at least hourly observations', true, 1),
  ('fb7a28e7-741d-53af-8046-0a6ada1c9b93', '6f02ffec-70ff-5e7f-995a-500699780d27', 'C', 'Continue 12-hourly observations', false, 2),
  ('a2db1c26-01fd-5886-844b-f43031627866', '6f02ffec-70ff-5e7f-995a-500699780d27', 'D', 'Increase observations to 4-hourly only', false, 3),
  ('958a8eef-5324-5463-ae51-93c69d86cd61', '6f02ffec-70ff-5e7f-995a-500699780d27', 'E', 'Discharge planning', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a86a001c-ea53-588d-b83a-e0240dffbcb6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 30 year old man has been intubated for a head injury. His GCS before intubation was E1 V2 M4. What was his GCS score and what does it indicate?', 'GCS = eyes (1-4) + verbal (1-5) + motor (1-6). Here 1 + 2 + 4 = 7. Severe head injury is GCS 8 or below, moderate 9-12 and mild 13-15. A GCS of 8 or below usually needs airway protection by intubation. Motor scores: 4 is withdrawal, 3 abnormal flexion (decorticate) and 2 extension (decerebrate).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bcaf00e5-8f8f-57d7-97f4-aad8ef2f55a5', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'A', '5 — mild head injury', false, 0),
  ('933ae18b-0bb0-516e-9e52-021441a2b9d8', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'B', '7 — severe head injury', true, 1),
  ('b910977d-ca34-562f-807d-bd1ad52f2df0', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'C', '7 — mild head injury', false, 2),
  ('99dbfb85-2943-5a10-bca4-2fbdc732d6fc', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'D', '9 — moderate head injury', false, 3),
  ('93268355-2e0e-5739-a435-b80864151df8', 'a86a001c-ea53-588d-b83a-e0240dffbcb6', 'E', '11 — moderate head injury', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 42 year old woman in ICU after a road traffic accident has a head injury with intracranial pressure of 30 mmHg. Her MAP is 80 mmHg. What is her cerebral perfusion pressure?', 'Cerebral perfusion pressure = MAP - ICP = 80 - 30 = 50 mmHg. The target CPP in traumatic brain injury is usually 60-70 mmHg. Raised ICP is managed by head-up positioning (30 degrees), sedation, normocapnia, osmotherapy (mannitol or hypertonic saline) and neurosurgical intervention. Cushing''s triad (hypertension, bradycardia, irregular breathing) is a late sign of raised ICP.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('163c10f7-3dce-55fc-ac89-df720f215974', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'A', '2.7 mmHg', false, 0),
  ('ade56a8b-2c72-5bd2-a49d-faedc761adbd', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'B', '30 mmHg', false, 1),
  ('031f9ed5-0078-5593-845e-e515655657fb', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'C', '50 mmHg', true, 2),
  ('71b45d33-87b4-5ff7-8ae6-4812c908110f', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'D', '80 mmHg', false, 3),
  ('afb5dfa1-c0c9-5d56-be88-db62ea182747', 'ca21e8e8-e721-5036-aaa7-ef2c06cd32e1', 'E', '110 mmHg', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 60 year old man in ICU has had a temperature of 38.6°C, new purulent tracheal secretions and a new infiltrate on chest X-ray 4 days after intubation. What is the SINGLE most likely diagnosis?', 'VAP occurs more than 48 hours after intubation. Organisms include Pseudomonas, MRSA and Gram-negative bacteria. Prevention bundles include head-of-bed elevation to 30-45 degrees, daily sedation holds, subglottic suctioning and oral care. Treatment is broad-spectrum antibiotics according to local guidance, narrowed on culture results.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3c4e5640-b2b4-5c21-b438-6645912530d5', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'A', 'Pulmonary embolism', false, 0),
  ('0c8fad95-7c03-5f60-a71d-e06301b7b4b0', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'B', 'Community-acquired pneumonia', false, 1),
  ('2a8d9b0f-b346-5ee8-bbca-10a819c65d92', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'C', 'Ventilator-associated pneumonia', true, 2),
  ('10d484b3-8f1f-5601-ae4f-7807d32ff1b4', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'D', 'Aspiration of gastric contents on admission', false, 3),
  ('879cf11a-c141-57d2-9f2c-641a5665f86b', 'def64f4d-2cf6-57d0-90b1-9e3a01783d26', 'E', 'Atelectasis only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 22 year old man has been brought in after a head injury. CT shows a large haemorrhage and he has fixed dilated pupils, no cough or gag reflex and no respiratory effort. Brainstem death testing is planned. Which condition must be met before testing?', 'Before brainstem testing, there must be irreversible brain damage of known cause, with reversible causes excluded (depressant drugs, hypothermia, metabolic and endocrine disturbance, neuromuscular blockade). Two sets of tests are done by two senior doctors. They test pupillary, corneal, vestibulo-ocular, gag and cough reflexes, motor response to pain in the cranial nerve distribution, and apnoea. EEG is not required in the UK.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('eebe1d73-827e-5c17-9555-1a8b636b43af', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'A', 'Patient must be awake', false, 0),
  ('339e2051-516e-560d-ace4-5184df95b768', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'B', 'Family must agree to organ donation', false, 1),
  ('ee73aead-629c-5ef4-9fa0-f6298039fe94', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'C', 'Exclusion of reversible causes (sedatives, hypothermia, metabolic and endocrine disturbance)', true, 2),
  ('3cc415be-16cf-54d4-8ded-bf37b4a43ab5', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'D', 'The patient must have been in ICU for 1 month', false, 3),
  ('49652ca7-ba67-5816-9728-015eb14aaac1', '8f2496ba-7b7d-5828-bb1c-5cb4caead321', 'E', 'An EEG must be flat', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7da34d6b-21a4-58ff-8741-016c8868bca2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 70 year old woman is in ICU with severe pancreatitis. She has been nil by mouth for 5 days and cannot eat. Her gut is functioning. What is the SINGLE most appropriate nutritional support?', 'Nutritional support is considered for patients who have eaten little or nothing for over 5 days or are malnourished. Enteral feeding is preferred over parenteral when the gut works, because it maintains gut integrity and reduces infections. In acute pancreatitis, enteral feeding is preferred. Re-feeding syndrome (hypophosphataemia) must be monitored for.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f10b0901-4245-56ed-b729-cf763a9de40f', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'A', 'Nil by mouth until full recovery', false, 0),
  ('173f4993-7508-5cd8-8792-91214b345d30', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'B', 'IV 5% glucose only', false, 1),
  ('51a4cf47-93fb-5b2d-bab6-7cfd3eaaccdb', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'C', 'Enteral feeding via nasogastric (or nasojejunal) tube', true, 2),
  ('bd51382c-4014-583c-9a8f-aff4ea5dc1be', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'D', 'Oral fluids only', false, 3),
  ('b39759a0-d610-5062-a742-0243028ae337', '7da34d6b-21a4-58ff-8741-016c8868bca2', 'E', 'Total parenteral nutrition as first-line', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 62 year old man with chronic alcohol use and low intake for weeks is started on nasogastric feeding. Three days later he has confusion, weakness and heart failure. His phosphate is 0.3 mmol/L. What is the SINGLE most likely diagnosis?', 'Refeeding syndrome happens when feeding restarts after starvation. Insulin release drives phosphate, potassium and magnesium into cells, causing low levels, fluid retention, heart failure, arrhythmias and neurological problems. High-risk patients should start feeding slowly (as low as 5-10 kcal/kg/day), with thiamine and B vitamins, and daily monitoring and replacement of electrolytes (NICE CG32).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('027e0df3-6721-5009-bcc7-7d4e37997ca7', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'A', 'Refeeding syndrome', true, 0),
  ('8dfdbdf9-12cb-5480-8988-bfe5bf2815b2', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'B', 'Delirium tremens', false, 1),
  ('7df24d9a-677c-5969-9923-6f93eb002bc7', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'C', 'Hepatic encephalopathy', false, 2),
  ('590eb2a2-2b53-5ddd-933f-516506ae785f', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'D', 'Hyperkalaemia', false, 3),
  ('b35488ac-3eb7-5186-b060-4bab227f7318', '2afea87c-ebbd-52d6-9276-c575e6e9c7de', 'E', 'Wernicke''s encephalopathy only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4674da67-c399-5eef-a5fa-ed047d3b00bc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 65 year old man is ventilated in ICU and his ABG shows pH 7.48, PaCO2 3.6 kPa, PaO2 14 kPa and bicarbonate 24 mmol/L. What is the SINGLE most likely acid-base disturbance?', 'High pH with low PaCO2 and normal bicarbonate indicates an uncompensated respiratory alkalosis, here probably from over-ventilation, which is corrected by reducing the minute ventilation. Other causes include anxiety, pain, PE, early sepsis, salicylates and pregnancy. Metabolic alkalosis (high bicarbonate) happens with vomiting, diuretics and hyperaldosteronism.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3f4ec3e2-d816-5ec5-831d-bd633cf49f90', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'A', 'Metabolic alkalosis', false, 0),
  ('f7eeddea-19e8-5cd0-8a9a-176fa9b7d757', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'B', 'Respiratory alkalosis', true, 1),
  ('1875aa6a-41aa-5cdb-a48d-782d8a577351', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'C', 'Normal', false, 2),
  ('b72cc5d3-0d49-504e-9c0f-4630e6881289', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'D', 'Respiratory acidosis', false, 3),
  ('7c220228-26b4-59f1-bcd9-f73cf35cc6ef', '4674da67-c399-5eef-a5fa-ed047d3b00bc', 'E', 'Metabolic acidosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b597b7f6-34be-5f23-8687-47fe607f06a0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 42 year old man attends his GP about a mole on his back that his partner noticed has grown over the past 3 months. It measures 9 mm, has irregular edges and contains several shades of brown and black. It occasionally itches. He has fair skin and a history of sunburn. What is the SINGLE most appropriate management?', 'Using the weighted 7-point checklist, change in size, irregular shape and irregular colour score 2 each (major features), and diameter of 7 mm or more and itch (change in sensation) score 1 each. A total of 3 or more prompts a suspected cancer referral for melanoma. Lesions suspected to be melanoma should not be excised in primary care, because complete diagnostic excision with appropriate margins is needed for accurate staging.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9bef387a-5f9d-52f4-a052-83559c7e6c28', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'A', 'Cryotherapy in the GP surgery', false, 0),
  ('cb868f2b-a405-5eab-8c13-b760e053795e', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'B', 'Suspected cancer pathway (two-week wait) referral to dermatology', true, 1),
  ('f05025c0-a3eb-5c00-9986-d872e54b1a46', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'C', 'Excise the lesion in the GP surgery', false, 2),
  ('fcefc566-9beb-5f06-a011-b63b8bcb8a08', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'D', 'Prescribe topical hydrocortisone and review in 2 weeks', false, 3),
  ('94f3fd30-7833-582f-8bfc-71fd9a0d653a', 'b597b7f6-34be-5f23-8687-47fe607f06a0', 'E', 'Reassure and review in 6 months', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b3d819cb-bf66-5ad3-af35-d99890b9a353', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 68 year old retired farmer has a slowly growing lesion on the side of his nose for 1 year. It is a pearly, rolled-edge nodule with fine telangiectasia on its surface and a central ulcer. He has no other lesions or lymph nodes. What is the SINGLE most likely diagnosis?', 'A pearly nodule with rolled edges, telangiectasia and central ulceration (''rodent ulcer'') on a sun-exposed site is basal cell carcinoma, the most common skin cancer. It grows slowly and very rarely spreads, so most are referred routinely (not via a suspected cancer pathway) unless there is concern about the site or size. Treatment is surgical excision or Mohs surgery for facial lesions. SCC grows faster and is keratotic, and can metastasise.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('72995f83-3cb1-521b-b20c-b84ef58486f8', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'A', 'Squamous cell carcinoma', false, 0),
  ('43b43f64-5e1d-55cd-95d1-a8cf811b8499', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'B', 'Keratoacanthoma', false, 1),
  ('a83a2cfb-669a-5880-b6f9-c256e6d5cf9f', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'C', 'Seborrhoeic keratosis', false, 2),
  ('6d50121c-e7f2-58d5-972e-e3e9c5e434d6', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'D', 'Basal cell carcinoma', true, 3),
  ('0e7dcb88-0c2b-5eaa-9052-f7c3830e7423', 'b3d819cb-bf66-5ad3-af35-d99890b9a353', 'E', 'Malignant melanoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cc9215bc-851d-55b3-be43-38a849ebbfe6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 34 year old man has well-demarcated, salmon-pink plaques with silvery scale on his elbows, knees and scalp. His nails show pitting and onycholysis. Emollients have been tried. What is the SINGLE most appropriate first-line topical treatment for his body plaques?', 'This is chronic plaque psoriasis. NICE recommends a potent corticosteroid applied once daily plus a vitamin D analogue (such as calcipotriol) once daily, applied separately at different times of day, for up to 4 weeks for trunk and limb plaques. Phototherapy and systemic agents (such as methotrexate) are for extensive or resistant disease. Nail changes are linked to psoriatic arthritis, so ask about joint symptoms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('887f783c-7d25-567a-aa2e-c0ed6c9640c8', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'A', 'Topical permethrin', false, 0),
  ('a6734ba1-1a40-556e-ac8a-bf56fe43f943', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'B', 'Topical aciclovir', false, 1),
  ('a6799d2e-a1e1-55e8-b818-e796267d14bb', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'C', 'Oral methotrexate as first-line', false, 2),
  ('a99f1771-3ef1-5dbf-8ae7-6676a666812f', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'D', 'Potent topical corticosteroid once daily plus topical vitamin D analogue once daily, applied at different times', true, 3),
  ('d0594c4c-6270-5999-83c2-4f93b83a795f', 'cc9215bc-851d-55b3-be43-38a849ebbfe6', 'E', 'Topical antifungal cream', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 3 year old girl with known atopic eczema becomes unwell with a fever. Her eczema has rapidly worsened over 24 hours, with clusters of painful punched-out erosions and vesicles on her face and neck. What is the SINGLE most appropriate management?', 'Rapidly worsening painful eczema with clustered punched-out erosions and fever is eczema herpeticum (HSV infection of eczematous skin), a dermatological emergency. It needs urgent same-day referral and oral or IV aciclovir. If the eyes are involved, refer to ophthalmology. Topical steroids should be avoided on affected areas until treatment has started.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('260b19cc-38ab-594a-b516-5c3db0f07f4b', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'A', 'Topical tacrolimus', false, 0),
  ('52ea2cfa-a1d2-53b4-b66e-81f43a787526', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'B', 'Emollients only and review in 1 week', false, 1),
  ('f616591f-18d3-516a-8c98-0229e33e5485', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'C', 'Increase topical steroid potency', false, 2),
  ('7d8d3818-6f02-5b58-9e98-be6b1deb8ecc', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'D', 'Oral flucloxacillin alone', false, 3),
  ('abf95684-37c6-5829-8085-bca92ed90f48', '3cf6e02d-61d8-5ed6-844f-4d2ed3e5dfd6', 'E', 'Urgent same-day referral and systemic aciclovir', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c9696926-6859-5b6b-8778-059cb6752fb2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 26 year old woman has 4 weeks of an intensely itchy rash that is worse at night. Her partner has similar symptoms. There are small papules and burrows between her fingers and on the flexor surfaces of her wrists. What is the SINGLE most appropriate treatment?', 'Itch that is worse at night, burrows in the finger webs and wrists, and affected contacts suggest scabies (Sarcoptes scabiei). Permethrin 5% cream is applied to the whole body from the neck down (including the scalp and face in young children and older people), left on for 8-12 hours, and repeated after 7 days. All household and sexual contacts must be treated at the same time, and bedding and clothing washed at 50°C or above. Itch can persist for up to 4 weeks after treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fc3ff886-5de1-540a-8dd1-9d548e0c2344', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'A', 'Oral flucloxacillin', false, 0),
  ('87671ffe-8d87-5493-9fd2-9d867b269320', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'B', 'Potent topical steroid', false, 1),
  ('0748faeb-a033-5a7f-9aa5-f63b45d8e341', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'C', 'Oral antihistamine only', false, 2),
  ('38034e47-48cc-55c1-acbf-08118dbd8e8e', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'D', 'Topical clotrimazole', false, 3),
  ('6c0253ed-5e8c-5627-b9af-a5994179800c', 'c9696926-6859-5b6b-8778-059cb6752fb2', 'E', 'Permethrin 5% cream applied to the whole body, repeated after 7 days, and treat all close contacts at the same time', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('866b7d3d-7455-5b1a-8988-b0c583824417', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 16 year old boy has comedones, inflammatory papules and some pustules on his face. There are no nodules or scars. Over-the-counter treatments have not helped. What is the SINGLE most appropriate first-line treatment?', 'NICE recommends a 12-week course of a fixed topical combination for mild-moderate acne: adapalene/benzoyl peroxide, tretinoin/clindamycin or benzoyl peroxide/clindamycin. Moderate-severe acne can have a topical treatment plus an oral tetracycline (lymecycline or doxycycline) for up to 6 months. Isotretinoin is specialist-only for severe or scarring acne, with a Pregnancy Prevention Programme and mood monitoring.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c648670e-187c-5363-b8cd-f02f089ac96b', '866b7d3d-7455-5b1a-8988-b0c583824417', 'A', 'Oral isotretinoin', false, 0),
  ('bcb242c6-6e6f-512c-97f3-e032613aa304', '866b7d3d-7455-5b1a-8988-b0c583824417', 'B', 'Oral doxycycline alone', false, 1),
  ('e72efd34-e7d8-5744-b484-08f0fc77747a', '866b7d3d-7455-5b1a-8988-b0c583824417', 'C', 'Topical steroid', false, 2),
  ('d93b8b7f-1253-584c-af02-b9b7bb3373a2', '866b7d3d-7455-5b1a-8988-b0c583824417', 'D', 'Oral trimethoprim', false, 3),
  ('6c4952f6-8e1f-525e-acd3-af573bfed820', '866b7d3d-7455-5b1a-8988-b0c583824417', 'E', 'A fixed topical combination (e.g. adapalene with benzoyl peroxide) for 12 weeks', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 42 year old woman has facial flushing, redness, telangiectasia and papules and pustules on her cheeks and nose. Her eyes are gritty. There are no comedones. Hot drinks and alcohol make it worse. What is the SINGLE most likely diagnosis?', 'Rosacea causes facial flushing, persistent redness, telangiectasia and papulopustules without comedones, often with eye involvement and triggers (heat, alcohol, spicy food, sunlight). Treatment is trigger avoidance, sunscreen, topical ivermectin, azelaic acid or metronidazole for papulopustular disease, brimonidine for erythema, and oral doxycycline for moderate-severe disease. Rhinophyma can develop.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('49909d26-1da1-589a-8497-f6713e7945cd', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'A', 'Carcinoid syndrome', false, 0),
  ('2952b4e3-9914-566d-98ae-9b31a9d2f778', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'B', 'Rosacea', true, 1),
  ('644a8e7f-f603-5b24-b6fc-984bbd2be8bb', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'C', 'Seborrhoeic dermatitis', false, 2),
  ('ad6f4af2-c253-5d87-a394-7b89424a5095', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'D', 'Acne vulgaris', false, 3),
  ('93b452a9-bfde-58a0-be83-64663a7dbd30', '50c6d15b-03a2-5f07-8ebe-7c8b21abf1f0', 'E', 'SLE', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6896da25-7d70-53a4-b40d-bc090b8c6f98', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 30 year old man has had an itchy, scaly rash on his scalp, eyebrows, nasolabial folds and behind his ears for months. It is worse in winter and with stress. What is the SINGLE most appropriate treatment?', 'Seborrhoeic dermatitis is an inflammatory reaction linked to Malassezia yeast, affecting sebaceous areas (scalp, face, chest). Treatment is topical antifungals (ketoconazole shampoo and cream), with short courses of mild topical steroids for flares. Severe or sudden seborrhoeic dermatitis can be a sign of HIV or Parkinson''s disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a2c532b3-a20b-5c18-a148-a10de3e5aaf0', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'A', 'Ketoconazole 2% shampoo and cream', true, 0),
  ('d537ab46-bd0b-5649-9ea8-2ffc21682a51', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'B', 'Oral terbinafine', false, 1),
  ('5b8c2612-9f3d-598e-95b4-1e4bafc461a2', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'C', 'Oral isotretinoin', false, 2),
  ('4b263c53-f872-5af5-b7eb-360fa541d91a', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'D', 'Permethrin', false, 3),
  ('8a3f81ca-7e39-5e0b-a9b5-a5e5b3c13333', '6896da25-7d70-53a4-b40d-bc090b8c6f98', 'E', 'Potent topical steroid long-term on the face', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('df1572ab-e500-546e-9976-8c6da6bc0b68', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 14 year old girl has had a single large oval scaly pink patch on her trunk for 5 days, followed by smaller oval patches in a ''Christmas tree'' pattern on her back. She is otherwise well. What is the SINGLE most likely diagnosis?', 'Pityriasis rosea starts with a herald patch, followed by smaller oval patches along skin cleavage lines in a ''Christmas tree'' distribution. It may be linked to HHV-6/7. It is self-limiting over 6-12 weeks, and emollients and antihistamines help itch. Secondary syphilis should be considered in sexually active people because it can look similar, including on the palms and soles.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a0f5e320-8d80-53c8-ad91-67ac9ed645e5', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'A', 'Tinea corporis', false, 0),
  ('238d1373-fe0e-5814-948f-4bcf7d595cf4', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'B', 'Pityriasis rosea', true, 1),
  ('3655cf28-69ad-5ba1-9312-1e770c488951', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'C', 'Psoriasis', false, 2),
  ('47a455bc-765c-5d75-9f51-95c0dab9ce19', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'D', 'Secondary syphilis', false, 3),
  ('f18df559-946e-5a20-ba8b-05dc8ffa3b67', 'df1572ab-e500-546e-9976-8c6da6bc0b68', 'E', 'Pityriasis versicolor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b080f3c2-d85f-5389-a135-39465c23eefc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 55 year old man has itchy, purple, flat-topped polygonal papules on the flexor surfaces of his wrists, with fine white lines on top. There is a white lacy pattern on his buccal mucosa. What is the SINGLE most likely diagnosis?', 'Lichen planus causes the 5 Ps: purple, pruritic, polygonal, planar papules and plaques, with Wickham''s striae, often on the flexor wrists, plus oral white lacy lesions. The Koebner phenomenon (lesions at sites of trauma) occurs. It may be drug-induced or linked to hepatitis C. Treatment is potent topical steroids, with oral steroids or phototherapy if widespread.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b7d8c0f0-d515-5902-9c18-3d99dc037a63', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'A', 'Eczema', false, 0),
  ('1fd34408-caed-568b-ac1b-bee3940f59be', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'B', 'Pityriasis rosea', false, 1),
  ('97edb3b5-a6df-5919-951a-9e1a602c292a', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'C', 'Scabies', false, 2),
  ('45732e9d-91df-5400-9f74-b0f0c37ba4f0', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'D', 'Psoriasis', false, 3),
  ('c2a41151-0337-5cce-90a2-fe7bcf00b6f0', 'b080f3c2-d85f-5389-a135-39465c23eefc', 'E', 'Lichen planus', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 72 year old man has tense, fluid-filled blisters on his trunk and limbs on an urticarial background, with severe itching. There are no mouth lesions. Skin biopsy with immunofluorescence shows linear IgG and C3 at the basement membrane. What is the SINGLE most likely diagnosis?', 'Bullous pemphigoid is an autoimmune subepidermal blistering disease of older people, with tense blisters (rarely in the mouth) and linear basement membrane deposits. Pemphigus vulgaris has flaccid intraepidermal blisters that break easily into erosions, often with mouth involvement, a positive Nikolsky sign and intercellular IgG. Pemphigoid is treated with potent topical or oral steroids and doxycycline.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8e10c4ab-39ea-55b8-9635-10716f36249e', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'A', 'Bullous pemphigoid', true, 0),
  ('69b51344-656f-5aa6-afd3-6d0057ca5dd9', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'B', 'Dermatitis herpetiformis', false, 1),
  ('87eb12f0-d716-5ee9-86fc-a9e5136d9a3a', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'C', 'Stevens-Johnson syndrome', false, 2),
  ('3264c7c2-c67e-5d05-93f6-dd337a48acf2', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'D', 'Pemphigus vulgaris', false, 3),
  ('1d5c519f-97a8-5170-bf52-14a86d84bef0', '65b6e2a3-5b69-5ca3-a99e-4c5d8b69b244', 'E', 'Bullous impetigo', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b32355b8-6c4b-590b-bf87-633ac6de817f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 28 year old woman was started on lamotrigine 2 weeks ago. She now has a fever, painful red skin with blistering and peeling over 20% of her body, and ulcers in her mouth, eyes and genitals. What is the SINGLE most likely diagnosis?', 'SJS/TEN is a severe mucocutaneous drug reaction with epidermal necrosis and mucosal involvement (SJS under 10% body surface area, overlap 10-30%, TEN over 30%). Causes include lamotrigine, carbamazepine, allopurinol, sulfonamides and NSAIDs. The drug must be stopped immediately and the patient managed in a burns or ICU setting with ophthalmology input. SCORTEN predicts mortality.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('93c8906c-fb0e-5a49-99d0-e449fc820eff', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'A', 'Drug reaction with eosinophilia (DRESS)', false, 0),
  ('b734ece6-450d-5085-9d45-5749de02d413', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'B', 'Bullous pemphigoid', false, 1),
  ('d516d661-432c-536f-94bc-f057855677f6', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'C', 'Stevens-Johnson syndrome / toxic epidermal necrolysis', true, 2),
  ('0b770398-471f-551f-a0e1-249706fa0cdf', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'D', 'Staphylococcal scalded skin syndrome', false, 3),
  ('43efe737-844b-5f1b-8cc2-a3e4188289a1', 'b32355b8-6c4b-590b-bf87-633ac6de817f', 'E', 'Erythema multiforme minor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('27f4561f-eba8-53ef-9a08-2eebe90834ca', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 7 year old girl has target lesions with a dark centre, pale zone and red outer ring on her hands, feet and limbs. She had cold sores last week. She has no significant mucosal involvement. What is the SINGLE most likely diagnosis?', 'Erythema multiforme causes typical target lesions, often on the extremities, most commonly triggered by HSV and sometimes Mycoplasma or drugs. EM minor has little or no mucosal involvement and is self-limiting. Recurrent HSV-associated EM can be prevented with antiviral prophylaxis. It is distinct from SJS/TEN.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('df41fb73-cf93-5b40-8ff0-6fa55f46687b', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'A', 'Stevens-Johnson syndrome', false, 0),
  ('ce000d06-aef0-50cf-a5c5-1f067a7aa72d', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'B', 'Urticaria', false, 1),
  ('93cf212d-70bb-5342-9b50-41c112f3a51b', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'C', 'Lyme disease', false, 2),
  ('9b8701bd-5932-5061-9997-af78ce7cc3dd', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'D', 'Kawasaki disease', false, 3),
  ('18a0de2d-fe17-5c36-8dda-e830bae0c767', '27f4561f-eba8-53ef-9a08-2eebe90834ca', 'E', 'Erythema multiforme', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('135075e9-425e-5a5b-a9d9-85668dd5b962', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 38 year old woman has tender, red-purple nodules on both shins for 2 weeks. She has had a dry cough. Her chest X-ray shows bilateral hilar lymphadenopathy. What is the SINGLE most likely diagnosis?', 'Erythema nodosum is a panniculitis causing tender red nodules on the shins. Causes include streptococcal infection, sarcoidosis, IBD, TB, pregnancy, the COCP and drugs (sulfonamides). Investigation of the cause includes a chest X-ray, throat swab or ASOT, and inflammatory markers. It is usually self-limiting over 6-8 weeks, treated with rest and NSAIDs.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('df6fd929-a2a0-51bf-a75a-45afd9c68c68', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'A', 'Cellulitis', false, 0),
  ('5a2b57d8-631f-589f-b38f-93a8b457b621', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'B', 'Insect bites', false, 1),
  ('c45ae1e4-997d-5e52-bc21-8b21fcda6038', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'C', 'DVT', false, 2),
  ('2fdf069b-7006-53c7-a787-84e876963844', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'D', 'Vasculitis', false, 3),
  ('b02fe751-f224-5ae7-828c-a300ea91bf70', '135075e9-425e-5a5b-a9d9-85668dd5b962', 'E', 'Erythema nodosum due to sarcoidosis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7fd79224-89e0-5510-b4a9-c9aa0d864610', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 25 year old man has had several weeks of itchy, red, scaly annular plaques with central clearing and an active scaly edge on his trunk. Skin scrapings show fungal hyphae. What is the SINGLE most appropriate treatment?', 'Tinea corporis (ringworm) is a dermatophyte infection causing annular scaly plaques with central clearing and an advancing edge. Topical antifungals are first-line. Extensive or resistant infection, scalp (tinea capitis) or nail involvement needs oral antifungals (terbinafine or griseofulvin). Steroids alone worsen it (''tinea incognito'').', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('10048a85-27ba-5bce-8d32-c923b36f8d3d', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'A', 'Oral aciclovir', false, 0),
  ('5b36f1c3-96cf-5c9d-9209-7c68f474f52b', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'B', 'Topical antibiotic', false, 1),
  ('9bb39747-d213-5c40-b526-9b6209b6a553', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'C', 'Topical imidazole (e.g. clotrimazole) or terbinafine cream', true, 2),
  ('2178b78b-80eb-5d3c-baca-68d138e57903', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'D', 'Oral isotretinoin', false, 3),
  ('82dbddbf-7a5c-5972-99d8-e1ca0be5b45c', '7fd79224-89e0-5510-b4a9-c9aa0d864610', 'E', 'Potent topical steroid alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('06c6c981-1059-59a4-90e7-cccd8be5b97b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 45 year old man has thickened, yellow, crumbly toenails on both big toes for a year. Nail clippings confirm a dermatophyte infection. The nails are painful and he wants treatment. What is the SINGLE most appropriate treatment?', 'Dermatophyte onychomycosis is confirmed by nail clippings before treatment. Oral terbinafine is first-line (6 weeks to 3 months for fingernails, 3-6 months for toenails), with LFTs checked. Itraconazole is the alternative, and is first-line for Candida. Amorolfine nail lacquer may be used for limited superficial disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('39f3f472-df24-5953-9fba-852136b87d22', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'A', 'Topical steroid', false, 0),
  ('e34888c7-be0d-55bd-80e4-fecb87b762fb', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'B', 'Oral terbinafine for 3-6 months (with LFT checks)', true, 1),
  ('5b310e09-bda5-50ec-b2d2-b637b12de797', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'C', 'Nail removal only', false, 2),
  ('c369ae43-b886-5073-a403-319fc28858e5', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'D', 'Oral fluconazole for 1 week', false, 3),
  ('6ab8884f-4170-58b2-9d71-cc004d510e55', '06c6c981-1059-59a4-90e7-cccd8be5b97b', 'E', 'Topical clotrimazole for 1 week', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9f95cea1-7119-58ee-8009-865aad4a294f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 32 year old man has well-defined hypopigmented and hyperpigmented scaly macules on his upper trunk, more obvious after sun exposure. A KOH preparation shows a ''spaghetti and meatballs'' appearance. What is the SINGLE most likely diagnosis?', 'Pityriasis versicolor is caused by Malassezia yeast and produces scaly macules that may be hypo- or hyperpigmented, usually on the trunk. Microscopy shows hyphae and spores (''spaghetti and meatballs''). Treatment is ketoconazole shampoo applied to affected skin, or oral itraconazole for extensive disease. Pigment changes may take months to resolve.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f12026a0-42f0-5366-9e69-09e94b156076', '9f95cea1-7119-58ee-8009-865aad4a294f', 'A', 'Tinea corporis', false, 0),
  ('81d78bda-abcc-5878-9ece-bf5b53c524d4', '9f95cea1-7119-58ee-8009-865aad4a294f', 'B', 'Pityriasis versicolor', true, 1),
  ('24ae7358-5afa-5e6c-9563-72f4e3c2796e', '9f95cea1-7119-58ee-8009-865aad4a294f', 'C', 'Vitiligo', false, 2),
  ('3e95915c-fa8c-50bf-9827-0d638f0e0abc', '9f95cea1-7119-58ee-8009-865aad4a294f', 'D', 'Pityriasis rosea', false, 3),
  ('5b9aa5c7-fc10-57c6-8db9-cb446568a0a0', '9f95cea1-7119-58ee-8009-865aad4a294f', 'E', 'Psoriasis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 35 year old woman has had depigmented white patches with sharp margins on her hands and around her mouth for 1 year. Wood''s lamp shows bright white fluorescence. She has hypothyroidism. What is the SINGLE most likely diagnosis?', 'Vitiligo is autoimmune loss of melanocytes, causing depigmented patches, often symmetrical and around the orifices and extremities. It is associated with other autoimmune diseases (thyroid disease, pernicious anaemia, type 1 diabetes, Addison''s). Treatment includes sun protection, camouflage, topical steroids or calcineurin inhibitors, phototherapy and topical ruxolitinib.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a8c4f58e-de96-5ec0-a3ff-66060e27eb72', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'A', 'Post-inflammatory hypopigmentation', false, 0),
  ('cc6e0fd5-42d8-55f9-a876-2a4b10208bcd', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'B', 'Leprosy', false, 1),
  ('cb3f24f1-5a10-5bdd-827d-a3d1e90be3ed', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'C', 'Vitiligo', true, 2),
  ('620f4514-53bf-5a6f-8439-e3cbb9e6d5c6', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'D', 'Albinism', false, 3),
  ('c86b8c9e-ce0e-58ac-9f2e-5e75638c8e3a', '1b7cb87c-6d71-5aa5-8ee1-2d0c1cd43ce5', 'E', 'Pityriasis versicolor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 70 year old farmer has a rapidly growing 1.5 cm keratotic nodule with a central keratin plug on the back of his hand, which appeared over 6 weeks. What is the SINGLE most appropriate management?', 'A rapidly growing keratotic nodule in sun-damaged skin may be squamous cell carcinoma or a keratoacanthoma, which is hard to tell apart clinically. NICE recommends a suspected cancer referral for suspected SCC. Treatment is surgical excision. SCC can metastasise. Risk factors include UV exposure, immunosuppression (transplant recipients) and actinic keratoses.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('df752c3e-a2d4-587e-966a-d22170d5919a', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'A', 'Topical steroid', false, 0),
  ('aa0f2de1-9b62-5e34-a36d-131ed3a4862b', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'B', 'Review in 6 months', false, 1),
  ('00c06ba8-181b-5ebf-b0c4-898b023b7b48', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'C', 'Suspected cancer pathway referral (possible squamous cell carcinoma or keratoacanthoma) for excision', true, 2),
  ('bf9b4e87-2971-5401-a79e-bda6092c5fdb', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'D', 'Reassure; likely a wart', false, 3),
  ('0f8eecb2-dd3b-5db2-a3b4-b4b223526b27', '7930312c-ffc9-5fcc-aaf1-755fbe3a664d', 'E', 'Cryotherapy in primary care', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 72 year old man has multiple rough, scaly, red patches on his bald scalp and the backs of his hands. They are not tender, indurated or rapidly growing. What is the SINGLE most likely diagnosis?', 'Actinic (solar) keratoses are premalignant lesions on sun-damaged skin with a small risk of becoming SCC. Treatment options include sun protection, topical 5-fluorouracil, imiquimod, diclofenac gel, cryotherapy and photodynamic therapy. Tenderness, induration, rapid growth or ulceration suggest SCC.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e009b105-a6c3-53a5-b7b8-1f0b78c7e3d4', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'A', 'Seborrhoeic keratoses', false, 0),
  ('4a146ace-3a77-59d6-bfa1-417cef5a8d79', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'B', 'Basal cell carcinoma', false, 1),
  ('faa9ddc6-4373-523e-b9a3-706dd5ea791b', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'C', 'Psoriasis', false, 2),
  ('60d397e2-000c-5156-bc0c-33769c7c5a3d', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'D', 'Actinic keratoses', true, 3),
  ('c719eb23-b072-52a1-89b9-e21e91f32a27', 'f4270ea2-9fa9-52da-af2b-e6fe66e5c6c9', 'E', 'Squamous cell carcinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('429d7902-3e9a-5501-80a5-00292d12d579', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 68 year old woman has multiple greasy, brown, ''stuck-on'', warty lesions on her back that have been present for years. They do not bleed. What is the SINGLE most appropriate management?', 'Seborrhoeic keratoses are common benign epidermal tumours in older people. They are waxy, warty and look ''stuck-on'', ranging from tan to dark brown. No treatment is needed. They can be removed by cryotherapy or curettage if irritated. A sudden eruption of many (the Leser-Trélat sign) may be associated with malignancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('db8aa844-01c3-51c6-96d8-a6ca86d9fc47', '429d7902-3e9a-5501-80a5-00292d12d579', 'A', 'Reassurance; seborrhoeic keratoses are benign (removal only for cosmetic reasons or if irritated)', true, 0),
  ('4e13345c-9b1a-58f3-a84a-6ea9150413c0', '429d7902-3e9a-5501-80a5-00292d12d579', 'B', 'Suspected cancer referral', false, 1),
  ('b7ad84ed-f2d0-5756-8947-7c1738d14f6e', '429d7902-3e9a-5501-80a5-00292d12d579', 'C', 'Oral antibiotics', false, 2),
  ('debb2f0d-cb44-5b78-9a10-8323c1c09220', '429d7902-3e9a-5501-80a5-00292d12d579', 'D', 'Topical 5-fluorouracil', false, 3),
  ('49527f6c-30c2-51b6-9dab-257f2aa11fac', '429d7902-3e9a-5501-80a5-00292d12d579', 'E', 'Excision of all lesions', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5c3684f0-8ded-5c60-8c2c-83741db5389d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 24 year old man develops itchy, raised, red wheals on his trunk that each last a few hours and then disappear, recurring daily for 8 weeks. He has no angioedema or systemic symptoms. What is the SINGLE most appropriate first-line treatment?', 'Chronic urticaria (more than 6 weeks) is usually spontaneous. First-line treatment is a daily non-sedating H1 antihistamine, increased up to four times the standard dose under specialist advice. Omalizumab is used in refractory cases. Triggers (NSAIDs, stress, heat) should be avoided. Individual wheals lasting over 24 hours or leaving bruising suggest urticarial vasculitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('18283177-4491-574f-aeef-a0ee8a1985d1', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'A', 'Oral antibiotics', false, 0),
  ('f37225de-2188-5c48-be40-84373de6fe42', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'B', 'Non-sedating H1 antihistamine (e.g. cetirizine), up to 4 times the standard dose if needed', true, 1),
  ('abe29a64-e9e6-5ba9-84a0-6a476e70d834', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'C', 'IM adrenaline', false, 2),
  ('6fd7a458-5b1a-57d5-814b-767d9f872754', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'D', 'Oral prednisolone long-term', false, 3),
  ('04e563c5-bdfb-5044-b2dc-79a003e4dd5b', '5c3684f0-8ded-5c60-8c2c-83741db5389d', 'E', 'Topical steroid', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1640f6fa-f6f4-5801-a70e-f79de32711a5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 40 year old woman has a painful, rapidly expanding ulcer on her leg with a purple, undermined edge. It started as a small pustule after a minor injury. She has ulcerative colitis. What is the SINGLE most likely diagnosis?', 'Pyoderma gangrenosum is a neutrophilic dermatosis causing painful ulcers with violaceous undermined edges. It can be triggered by trauma (pathergy). It is associated with IBD, rheumatoid arthritis and haematological malignancy. Debridement can make it worse. Treatment is potent topical or oral steroids, ciclosporin or biologics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('569cb40a-e427-5d9c-b9d3-f8b470d3b35a', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'A', 'Arterial ulcer', false, 0),
  ('200b4a7c-964e-5bca-8b19-c7ce8dfddf76', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'B', 'Erythema nodosum', false, 1),
  ('b961d7dc-5276-5225-a662-b2cd3466e3b0', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'C', 'Pyoderma gangrenosum', true, 2),
  ('e24f9fd3-9554-53d3-9fa7-4cd6ac732140', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'D', 'Venous ulcer', false, 3),
  ('0a58a93d-eb14-58b5-9250-ad8a629aa387', '1640f6fa-f6f4-5801-a70e-f79de32711a5', 'E', 'Necrotising fasciitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('12b64963-7473-57fd-9c27-cf9d019bf787', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 55 year old man has a painless, firm, pearly nodule growing over 6 months on his cheek with fine surface blood vessels. A dermatologist confirms nodular basal cell carcinoma. Which treatment offers the HIGHEST cure rate for a facial BCC in a high-risk site?', 'Mohs micrographic surgery examines all margins during the procedure, giving the highest cure rates while sparing tissue. It is preferred for high-risk BCCs (central face, around the eyes, nose and lips, recurrent, ill-defined or morphoeic). Standard surgical excision is used for most other BCCs. Superficial BCCs can be treated with imiquimod or photodynamic therapy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5cafa37d-71e3-5b03-a78a-0e38ff9a6d68', '12b64963-7473-57fd-9c27-cf9d019bf787', 'A', 'Cryotherapy', false, 0),
  ('8a852619-4b5d-5522-b945-abeb205d06e4', '12b64963-7473-57fd-9c27-cf9d019bf787', 'B', 'Curettage', false, 1),
  ('919859d3-cc8a-5fbb-becc-ce20a5b4888c', '12b64963-7473-57fd-9c27-cf9d019bf787', 'C', 'Radiotherapy as first-line for all', false, 2),
  ('9eb6d9f5-ace0-5486-b225-89237e78a9ca', '12b64963-7473-57fd-9c27-cf9d019bf787', 'D', 'Topical imiquimod', false, 3),
  ('a51e9560-7f65-53af-a12e-e49c590cd195', '12b64963-7473-57fd-9c27-cf9d019bf787', 'E', 'Mohs micrographic surgery', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 4 year old boy has a few small, pearly, umbilicated papules on his trunk for 2 months. He has atopic eczema. He is otherwise well. What is the SINGLE most appropriate management?', 'Molluscum contagiosum is a poxvirus infection causing umbilicated papules. It is common in children and usually resolves on its own within 18 months. Treatment is not usually needed, though children can keep attending school. Extensive or facial lesions in adults, or in immunocompromised people, warrant further assessment (including HIV in adults).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f5b09a0b-56fe-5747-ba05-8c5d494954a5', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'A', 'Reassurance; molluscum contagiosum usually resolves without treatment within 18 months', true, 0),
  ('baebfe69-285c-5dc7-adbc-ffd907c31af5', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'B', 'Topical steroid on lesions', false, 1),
  ('a581d2a4-0efc-513e-9c68-9fbc07fd6ee8', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'C', 'Oral antibiotics', false, 2),
  ('ca980dda-ef19-51d9-87c5-8a2796944b41', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'D', 'Oral aciclovir', false, 3),
  ('82635635-2cd8-541e-aadc-f343c60199f2', '9c4ce4d7-fc96-5da0-b665-21cf638b5f32', 'E', 'Cryotherapy for all lesions', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ffd96e9b-0c86-538f-8de2-869be987deac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 6 year old girl has an itchy, red rash with yellow crusting on her face and neck. Her mother has tried non-prescription creams but the rash has continued to spread. She is otherwise well. Her temperature is 36.9°C. She has a yellow crusting on the sores around her mouth. Which is the most likely diagnosis?', 'Honey-coloured (golden-yellow) crusted lesions around the mouth and face in a child are typical of impetigo, usually caused by Staphylococcus aureus. NICE recommends hydrogen peroxide 1% cream for localised non-bullous impetigo, topical fusidic acid if that is unsuitable, and oral flucloxacillin for widespread or bullous disease. The child should stay off school until the lesions have crusted or 48 hours after starting antibiotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e03d6e35-9a55-55a4-8648-e062f048c369', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'A', 'Chickenpox', false, 0),
  ('0eca1f06-fcbe-52c2-93dd-1f7bdc24f4fb', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'B', 'Fungal infection', false, 1),
  ('e16e404c-ccfe-52dd-bedb-b9dbe981dd6b', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'C', 'Impetigo', true, 2),
  ('f611c866-0c0a-597d-bae9-931cb1e92c4f', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'D', 'Measles', false, 3),
  ('de2fad3a-e2de-5aff-8796-e26cd51b43ae', 'ffd96e9b-0c86-538f-8de2-869be987deac', 'E', 'Psoriasis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 70 year old woman has a red and scaly rash on her trunk and is seen by the district nurses. She is bed bound and receiving treatment of a pressure sore. She has scratch marks on her limbs and trunk and scaling linear lesions on her hands and feet. Which is the most appropriate initial topical treatment for her rash?', 'Widespread itch with scratch marks and burrows (linear scaling lesions) on the hands and feet in a bed-bound patient suggests scabies, including possible crusted scabies. First-line treatment is permethrin 5% cream to the whole body, repeated after 7 days, with treatment of contacts. Crusted scabies may need oral ivermectin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2f041acf-60f2-5090-92c6-b3c5153ecf1a', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'A', 'Clobetasone', false, 0),
  ('0e7dee1b-c73d-5146-b693-0c6db635f0c9', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'B', 'Clotrimazole', false, 1),
  ('d3fd6861-5a2b-5e03-92ce-c442991f0146', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'C', 'Hydrocortisone', false, 2),
  ('bb1f596a-c62c-5822-a95e-7e8d84a700ab', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'D', 'Malathion', false, 3),
  ('7b751b58-02cb-5504-be4d-10de7fd9e345', '3ee98f2d-2bbc-5200-8a21-119f40bc3df6', 'E', 'Permethrin', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('58076c7b-22fc-5552-880e-67845bc71dab', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 23 year old woman has a mole on her leg which has recently changed in size, shape and appearance. She originally noticed it 3 years ago. It is not itchy and does not bleed.  [The image in the original paper shows an asymmetrical lesion with an irregular border and uneven pigmentation.] Which is the most likely diagnosis?', 'A mole that has changed in size, shape and appearance (asymmetry, irregular border, colour variation) suggests malignant melanoma. It needs a suspected cancer referral to dermatology (7-point checklist: change in size, shape or colour each score 2). (The original question shows an image; key features are described here.)', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('db974873-ef44-563c-93b2-987420b98d41', '58076c7b-22fc-5552-880e-67845bc71dab', 'A', 'Compound naevus', false, 0),
  ('e4abf186-a18e-5e70-8deb-f80e6e019022', '58076c7b-22fc-5552-880e-67845bc71dab', 'B', 'Giant naevus', false, 1),
  ('987b19f0-18ea-5da0-8247-39a4283ee54e', '58076c7b-22fc-5552-880e-67845bc71dab', 'C', 'Junctional naevus', false, 2),
  ('eed40612-2c20-5cd5-a564-6c72c8278dee', '58076c7b-22fc-5552-880e-67845bc71dab', 'D', 'Malignant melanoma', true, 3),
  ('f181422c-86f1-5da7-acea-66483ef03977', '58076c7b-22fc-5552-880e-67845bc71dab', 'E', 'Seborrhoeic keratosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f05b39fd-c380-5108-9975-2a33d8c54ad1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 12 year old boy has painful blisters which burst leaving shallow lesions. He has been feeling hot and unwell for last 5 days. He has eczema and uses emollients regularly.  [The image in the original paper shows clusters of punched-out erosions on eczematous skin.] Which is the most likely diagnosis?', 'Painful vesicles that burst into punched-out erosions, with fever and malaise, in a child with eczema is eczema herpeticum (HSV), a dermatological emergency. It needs urgent aciclovir and same-day referral. (The original question shows an image; key features are described here.)', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f0ecc26a-5ca7-5b37-b950-b9c985cef88d', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'A', 'Atopic eczema', false, 0),
  ('34d243c9-684b-5c90-aef4-98de58a57042', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'B', 'Chicken pox', false, 1),
  ('b16cb656-ac8c-5f95-9a64-4274c8cc47e2', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'C', 'Eczema herpeticum', true, 2),
  ('7ed49aeb-01da-57dd-b31d-41356162b251', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'D', 'Impetigo', false, 3),
  ('78dcd742-eb55-5e1f-a247-5e439a1eb47e', 'f05b39fd-c380-5108-9975-2a33d8c54ad1', 'E', 'Staphylococcal skin infection', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 9 year old boy is brought to the GP surgery with a nosebleed from his right nostril that started 5 minutes ago after he picked his nose. He is well, haemodynamically stable and has no history of bleeding disorders. What is the SINGLE most appropriate first-aid advice?', 'Most nosebleeds come from Little''s area (Kiesselbach''s plexus) on the anterior septum. First aid is to sit up, lean forward and pinch the soft cartilaginous part of the nose firmly for 10-15 minutes without letting go, and spit out blood rather than swallowing it. Tilting the head back makes the patient swallow blood. Cautery is used if a bleeding point is seen once bleeding has settled, and packing is used if first aid fails.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('09bf07d8-b375-5556-9e0e-8253ba71aa8c', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'A', 'Insert a nasal pack immediately', false, 0),
  ('b08287a3-700f-59ee-bdfb-31edeefa209f', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'B', 'Apply silver nitrate cautery immediately', false, 1),
  ('40a28bbd-32d6-5b53-a4b2-edcbc61d282c', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'C', 'Pinch the bony bridge of the nose for 2 minutes', false, 2),
  ('a74e028c-c2df-51fc-95fb-0de5e5c25e67', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'D', 'Lie flat and tilt the head back', false, 3),
  ('10fa9fd9-61b0-52d3-bdbd-dc735857d6b4', '89a49d90-2c66-54e1-8bb5-cbd3eae9f5e5', 'E', 'Sit forward and firmly pinch the soft part of the nose for 10-15 minutes', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 3 year old girl has had ear pain and a fever of 38.4°C for 1 day. Otoscopy shows a red, bulging left tympanic membrane. She is eating and drinking, is not systemically unwell, and has no ear discharge. She has had no previous ear infections. What is the SINGLE most appropriate management?', 'Acute otitis media is usually self-limiting within 3 days (up to 1 week). NICE recommends analgesia and either no antibiotic or a back-up prescription. Immediate antibiotics (amoxicillin for 5-7 days) are for children who are systemically unwell, at high risk of complications, under 2 years with bilateral infection, or with otorrhoea. Safety-net for signs of mastoiditis or meningitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('04a90d4f-73f1-534a-9d6c-d7719363b757', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'A', 'Oral amoxicillin for 5 days for all children', false, 0),
  ('9ad9ae56-47f2-53c0-a566-9328560ce165', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'B', 'Grommet insertion', false, 1),
  ('e71d035b-e2e5-5fbb-a1d8-623b5edf169d', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'C', 'Paracetamol or ibuprofen for pain, with no antibiotic or a delayed (back-up) prescription', true, 2),
  ('40d13d92-9e23-5b69-89d2-0b230b5f080c', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'D', 'Topical antibiotic ear drops', false, 3),
  ('4cbd4ca5-90b8-5aac-b54b-96502112adcb', '2ab89067-81d7-5940-8b5a-c6fa13d1eb89', 'E', 'Urgent ENT referral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('210abd1c-1fec-5e39-8250-d599325cdaa4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 22 year old man has 4 days of a worsening sore throat, now severe on the right side. He has a muffled ''hot potato'' voice, trismus and is drooling. His temperature is 38.7°C. There is swelling above and lateral to the right tonsil, with the uvula deviated to the left. What is the SINGLE most likely diagnosis?', 'Unilateral severe throat pain, trismus, a ''hot potato'' voice, drooling and uvular deviation away from the affected side are typical of quinsy, a complication of tonsillitis. It needs same-day ENT referral for needle aspiration or incision and drainage, IV antibiotics, analgesia and fluids. Tonsillectomy may be considered after recurrent episodes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5b22c929-0538-585d-856b-d27f2fd53ce9', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'A', 'Peritonsillar abscess (quinsy)', true, 0),
  ('f4eb3393-6849-53c5-be67-07efae4dd2cb', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'B', 'Acute epiglottitis', false, 1),
  ('d4654aeb-867f-562c-a9e5-4a4e700f8d16', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'C', 'Retropharyngeal abscess', false, 2),
  ('6976e3fb-ec89-574a-a247-adce6bd98639', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'D', 'Infectious mononucleosis', false, 3),
  ('2427ca71-5473-55e2-a13b-995398887030', '210abd1c-1fec-5e39-8250-d599325cdaa4', 'E', 'Tonsillar carcinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 58 year old woman has brief episodes of intense spinning lasting under a minute, triggered by turning over in bed or looking up. She has no hearing loss, tinnitus or other neurological symptoms. When her head is turned to the right and she is lowered quickly to lie back, she develops torsional upbeating nystagmus with vertigo after a short delay. What is the SINGLE most appropriate management?', 'Brief vertigo triggered by head position changes, with a positive Dix-Hallpike test (delayed torsional nystagmus that fatigues), is benign paroxysmal positional vertigo, caused by otoconia in the posterior semicircular canal. The Epley particle repositioning manoeuvre is curative in most patients. Vestibular suppressants are not helpful long-term. Betahistine is used for Ménière''s disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e2df411-7ac0-582a-8dfd-1282b163253a', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'A', 'Epley manoeuvre', true, 0),
  ('58b271f1-292c-549d-9297-905dd743f850', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'B', 'Urgent MRI brain', false, 1),
  ('304962dd-f3c1-50ad-8493-b860afc0008e', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'C', 'Betahistine', false, 2),
  ('1ff1af4a-61eb-53e5-8ffe-69edd3da44bf', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'D', 'Oral prednisolone', false, 3),
  ('93b72589-4580-56c2-870e-26e4ebc5e4e5', '41612f6d-3fc6-5e0c-b3b5-a82078b67c66', 'E', 'Long-term prochlorperazine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4c957391-4f42-5d4e-b042-1f9bba09dcec', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 45 year old man noticed this morning that he could not hear on the phone with his left ear. He has tinnitus in that ear but no pain or discharge. Otoscopy is normal. Rinne''s test is positive in both ears and Weber''s test lateralises to the right. What is the SINGLE most appropriate management?', 'Weber lateralising to the right with positive Rinne bilaterally indicates a left sensorineural hearing loss. Sudden onset within 72 hours means sudden sensorineural hearing loss, which needs immediate (same-day) referral to ENT or the emergency department. High-dose oral steroids may improve recovery if started early. An MRI is needed later to exclude a vestibular schwannoma.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9459ab11-6ffb-55dd-903c-3b4302729e06', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'A', 'Prescribe olive oil ear drops', false, 0),
  ('df80289a-3e86-5584-ba62-1ac5b1e7eba7', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'B', 'Oral amoxicillin', false, 1),
  ('b38241ad-c512-56bd-9cd6-d0293f3d8633', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'C', 'Urgent same-day ENT referral (within 24 hours)', true, 2),
  ('4c880e9a-fbe8-5820-a5fe-c4eda4cef554', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'D', 'Routine audiology referral', false, 3),
  ('853c9f73-e8a5-501d-b24e-61d03f3fc251', '4c957391-4f42-5d4e-b042-1f9bba09dcec', 'E', 'Reassure and review in 4 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 45 year old man has had a blocked nose and loss of smell for 6 months, with clear nasal discharge. Examination shows bilateral grey, mobile, insensitive polyps. He has asthma and is sensitive to aspirin. What is the SINGLE most appropriate first-line treatment?', 'Bilateral nasal polyps cause nasal obstruction, rhinorrhoea and anosmia, and are associated with asthma and aspirin sensitivity (Samter''s triad). First-line treatment is intranasal steroids, with a short course of oral steroids for severe disease and surgery (FESS) if medical treatment fails. Unilateral polyps, bleeding or crusting need urgent referral to exclude malignancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b8da25d1-4f49-572a-a203-82dbf927807f', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'A', 'Immediate surgery', false, 0),
  ('f0b4ffe4-65a1-5752-91f9-1f365af256fb', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'B', 'Decongestant spray long-term', false, 1),
  ('6336d972-72e3-50cd-a505-d534c6e10787', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'C', 'Intranasal corticosteroid drops or spray', true, 2),
  ('7050cb13-f830-57fa-a3ea-27c92426a2f4', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'D', 'Antibiotics', false, 3),
  ('ada04086-ad92-54c2-b607-b5a865767819', '2c4dc1d2-504c-5f88-b140-fdf09fa7eb5c', 'E', 'Antihistamines only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('409b1291-547e-5ff3-83b6-3b34bb6665e6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 34 year old woman has had nasal congestion, facial pain and pressure over her cheeks, and purulent nasal discharge for 5 days after a cold. She is afebrile and otherwise well. What is the SINGLE most appropriate management?', 'NICE: acute sinusitis is usually viral and resolves within 2-3 weeks. For symptoms under 10 days, give self-care advice and no antibiotics. For symptoms over 10 days without improvement, consider a high-dose nasal steroid, with a back-up antibiotic (phenoxymethylpenicillin). Red flags (periorbital swelling, visual change, severe headache) need urgent referral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ff72bdf6-8176-50ae-b4c1-8c45555e3112', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'A', 'Oral prednisolone', false, 0),
  ('265aca29-3089-5913-817a-138139d3168d', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'B', 'Urgent ENT referral', false, 1),
  ('a5dfff7e-035d-5a53-81a7-935a464e5d67', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'C', 'Self-care (analgesia, saline irrigation); no antibiotics, as most acute sinusitis is viral and self-limiting', true, 2),
  ('3fb3713f-4623-54e8-bbb5-813fdcac1fbd', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'D', 'CT sinuses', false, 3),
  ('03f5ac81-7825-5615-8cb4-5e33edae9fe0', '409b1291-547e-5ff3-83b6-3b34bb6665e6', 'E', 'Oral co-amoxiclav for 2 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9097d355-9db5-5ce1-b5f6-60105e5114e8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 72 year old man on aspirin has a nosebleed that has not stopped despite 20 minutes of firm pressure and cautery. He is haemodynamically stable. What is the SINGLE most appropriate next step?', 'If first aid and cautery fail, anterior nasal packing (a nasal tampon or ribbon gauze) is used, followed by admission or ENT review. Posterior bleeds (often in older people with hypertension or anticoagulation) may need posterior packing, sphenopalatine artery ligation or embolisation. Anticoagulation and clotting should be checked. Tranexamic acid can help.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ec1dc0b4-47b8-5479-b379-1969e1587bb3', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'A', 'Posterior packing first', false, 0),
  ('34ab436b-2578-54e1-a8bd-3e9ac643d2da', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'B', 'Anterior nasal packing (e.g. nasal tampon)', true, 1),
  ('f208be6b-3c75-5f92-9435-336d7abea84c', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'C', 'Immediate surgery', false, 2),
  ('d5b6f711-d2ea-5400-be65-93c3efc50a29', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'D', 'Discharge home', false, 3),
  ('29388486-41af-5479-9786-5df9d0f24237', '9097d355-9db5-5ce1-b5f6-60105e5114e8', 'E', 'IV vitamin K', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('eb15f895-cba9-5393-b177-8860a0d75f8a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 7 year old boy has had recurrent tonsillitis, with 8 episodes in the past year, each needing time off school. What is the SINGLE most appropriate management?', 'Tonsillectomy (SIGN criteria) is considered for 7 or more well-documented episodes in 1 year, 5 or more a year for 2 years, or 3 or more a year for 3 years, when episodes are disabling. Other indications include quinsy (two episodes) and obstructive sleep apnoea. Post-tonsillectomy haemorrhage, primary (within 24 hours) or secondary (5-10 days, often infection), is a key complication.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7a61fc1f-0a5f-5534-b94b-14517d53571f', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'A', 'Oral steroids', false, 0),
  ('3c48e9d8-5cb0-5732-872a-debcdb28ab7a', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'B', 'Long-term prophylactic antibiotics', false, 1),
  ('808db33d-d9b7-578b-9da2-2aacb1ba5098', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'C', 'Adenoidectomy only', false, 2),
  ('0ad1736f-8a92-5409-9b23-a604a57b3a35', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'D', 'Refer to ENT for consideration of tonsillectomy', true, 3),
  ('0b6393a5-c04b-550a-89b0-cc0613255d54', 'eb15f895-cba9-5393-b177-8860a0d75f8a', 'E', 'Reassure', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f288730c-6580-5e5b-9909-775b07559fbb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 3 year old boy has had hearing problems and speech delay. Otoscopy shows dull, retracted tympanic membranes with an air-fluid level, and tympanometry shows a flat (type B) trace bilaterally for 3 months. What is the SINGLE most appropriate management?', 'Otitis media with effusion (glue ear) is common in young children, causing conductive hearing loss. Most cases resolve, so active observation for 3 months is first-line. Persistent bilateral OME with hearing loss affecting speech or education warrants grommets (with or without adenoidectomy) or hearing aids. Children with Down syndrome or cleft palate are more prone to it. Unilateral glue ear in adults needs nasopharyngeal examination to exclude a tumour.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('68ebe70f-dc24-526a-8853-1b7621d8a40b', 'f288730c-6580-5e5b-9909-775b07559fbb', 'A', 'Antihistamines', false, 0),
  ('93b11dfc-445d-5819-8003-a774591fbdd4', 'f288730c-6580-5e5b-9909-775b07559fbb', 'B', 'Refer to ENT for consideration of grommets (ventilation tubes) or hearing aids', true, 1),
  ('9a3e1dce-8dcb-5121-9d5c-4316a6950c03', 'f288730c-6580-5e5b-9909-775b07559fbb', 'C', 'Reassure; no follow-up', false, 2),
  ('66e80b51-7492-5478-8ef3-dcfc7f8ac4c0', 'f288730c-6580-5e5b-9909-775b07559fbb', 'D', 'Oral steroids', false, 3),
  ('407dac7c-24c3-57b0-a380-07e5092369f8', 'f288730c-6580-5e5b-9909-775b07559fbb', 'E', 'Oral antibiotics for 6 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7091283d-be87-56f3-b7cc-1928e2bccbe8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 30 year old woman who swims regularly has had a painful, itchy right ear with discharge for 4 days. The ear canal is red and swollen with debris. Pulling the pinna is painful. The tympanic membrane is intact. What is the SINGLE most appropriate treatment?', 'Otitis externa is inflammation of the ear canal, often from swimming or trauma (cotton buds), commonly caused by Pseudomonas or Staphylococcus aureus. Treatment is topical antibiotic, with or without steroid drops, and keeping the ear dry. A wick may be needed if the canal is swollen shut. Malignant (necrotising) otitis externa in older people with diabetes is an emergency.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cc6817a7-e980-571f-828e-5a0db8a041b1', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'A', 'Oral amoxicillin', false, 0),
  ('1df0ab43-3365-5fd7-96b5-8cc9fc5e7990', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'B', 'Grommet insertion', false, 1),
  ('38dcad83-d2be-5a7c-b272-548dedf856cd', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'C', 'Oral steroids', false, 2),
  ('5b4570e9-1baf-503f-bcec-0e7bab7b84f2', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'D', 'No treatment', false, 3),
  ('8818a037-d8f8-5b04-b278-512170514e24', '7091283d-be87-56f3-b7cc-1928e2bccbe8', 'E', 'Topical antibiotic ± steroid ear drops (e.g. ciprofloxacin or neomycin with steroid)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d0ced757-ff1c-50ec-982e-e31980ca69dc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 74 year old man with diabetes has had severe ear pain and discharge for 3 weeks despite topical treatment. There is granulation tissue in the floor of the ear canal and he has a facial nerve palsy. What is the SINGLE most likely diagnosis?', 'Necrotising otitis externa is an invasive Pseudomonas infection spreading to the skull base, in older people with diabetes or the immunocompromised. It causes severe pain, discharge, granulation tissue in the canal and cranial nerve palsies (VII). It needs urgent ENT referral, CT or MRI imaging and prolonged IV antipseudomonal antibiotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('57012129-a659-5c42-aa91-7665d8cd6f2b', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'A', 'Necrotising (malignant) otitis externa', true, 0),
  ('b690f7fd-8853-5473-a34e-63c848250d94', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'B', 'Simple otitis externa', false, 1),
  ('7d2e5ec6-7a54-59fd-a38f-2225ed3f206e', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'C', 'Bell''s palsy', false, 2),
  ('21fe3d1c-5acf-5add-8098-b76257f30a11', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'D', 'Acute otitis media', false, 3),
  ('943f510e-214d-5d3a-9545-7c49917baba4', 'd0ced757-ff1c-50ec-982e-e31980ca69dc', 'E', 'Cholesteatoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e4ab7773-d95a-5998-a931-96dde465eaaf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 40 year old woman has had a chronic smelly discharge from her left ear and progressive hearing loss for a year. Otoscopy shows a pearly white mass with debris in the attic (pars flaccida) of the tympanic membrane. What is the SINGLE most likely diagnosis?', 'Cholesteatoma is keratinising squamous epithelium in the middle ear, often in the attic. It causes a foul discharge and conductive hearing loss, and can erode structures (ossicles, facial nerve, labyrinth, intracranial spread). It needs ENT referral for CT and surgical removal (mastoidectomy).', null, true, false, jsonb_build_object('source', 'plab1-xlsx')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
