  ('8c6ba3cb-1593-5821-afdc-250e9be8372e', '18dd1649-885d-59e8-a3a0-a5870f711673', 'B', 'Combined oral contraceptive', false, 1),
  ('7ef2a1ae-ea87-515e-9f24-fb799ba5597e', '18dd1649-885d-59e8-a3a0-a5870f711673', 'C', 'Long-term oral prednisolone', false, 2),
