  ('c362bb61-6055-54a2-9759-22d2cfea6f98', 'fde1c7f2-5399-5eae-9c65-989af2cc55b5', 'B', 'Ectopic pregnancy', false, 1),
  ('a999853c-3c5b-5eb1-9b0a-4e2237e49867', 'fde1c7f2-5399-5eae-9c65-989af2cc55b5', 'C', 'Appendicitis', false, 2),
  ('7a120607-e625-5a67-9704-5e37848356f9', 'fde1c7f2-5399-5eae-9c65-989af2cc55b5', 'D', 'Ovarian hyperstimulation syndrome', true, 3),
