  ('8188fd69-99f1-5d8f-86b7-655231dccbdb', 'ed92cb9d-431e-514e-9763-8f145d74d1b1', 'A', 'No treatment as it is not dangerous', false, 0),
  ('02bc4c44-4450-5864-959b-cca6a4d9d5a3', 'ed92cb9d-431e-514e-9763-8f145d74d1b1', 'B', 'Antibiotics', false, 1),
  ('2b8d38b1-eeb5-5c70-9f78-6f3b865bec45', 'ed92cb9d-431e-514e-9763-8f145d74d1b1', 'C', 'Mesh repair as first-line', false, 2),
