  ('b318fc9b-d241-5665-976b-7367fd25c573', '08fdf8a4-35fd-5c98-ace0-e4d3e8d4eb3e', 'A', 'Indwelling catheter', false, 0),
  ('341b8c9a-bfdb-56b4-8155-e81ea94a9334', '08fdf8a4-35fd-5c98-ace0-e4d3e8d4eb3e', 'B', 'Oxybutynin', false, 1),
