  ('90b0e816-c7c9-51db-aac1-328c131d39e1', 'a5d17c39-22dd-5306-9349-44822655dbb1', 'A', 'Doxycycline', false, 0),
  ('f0eb1a2c-f752-57d2-b6ae-3f59a2f3ce8a', 'a5d17c39-22dd-5306-9349-44822655dbb1', 'B', 'Clotrimazole pessary', false, 1),
  ('3ff37986-a3fc-51f7-8bb3-e8b467314bd8', 'a5d17c39-22dd-5306-9349-44822655dbb1', 'C', 'Oral metronidazole', true, 2),
  ('13f31d59-7af9-57fb-a6b4-6523260117f7', 'a5d17c39-22dd-5306-9349-44822655dbb1', 'D', 'Treat her male partner', false, 3),
