  ('2da73c41-f90a-5913-8470-49b566835fab', '52c65205-583e-59c0-ac5a-90d256573746', 'A', '1', false, 0),
  ('15570272-cedb-5bf1-bfbc-b3489e98b174', '52c65205-583e-59c0-ac5a-90d256573746', 'B', '2', false, 1),
